const FACTOS=[
{q:'¿Qué hacemos con el pulgar antes de escuchar el Evangelio?',a:'Tres cruces pequeñas: en la frente, en los labios y en el pecho',o:['Una sola cruz grande sobre el cuerpo','Nos golpeamos el pecho tres veces','Nos inclinamos hasta el suelo'],por:'Pedimos que Cristo esté en la mente, en las palabras y en el corazón.'},
{q:'¿Cuánto ayuno se pide antes de comulgar?',a:'Una hora antes (el agua y las medicinas no cuentan)',o:['Desde la medianoche','Seis horas','Ninguno'],por:'Es la norma actual de la Iglesia latina. Las personas enfermas o mayores tienen más flexibilidad.'},
{q:'¿Cuál es el momento central de la Misa?',a:'La Plegaria Eucarística, con la consagración',o:['La homilía','El Gloria','El rito de la paz'],por:'Por las palabras de la consagración, el pan y el vino se convierten en el Cuerpo y la Sangre de Cristo.'},
{q:'¿Cuántos sacramentos hay?',a:'Siete',o:['Tres','Cinco','Doce'],por:'Bautismo, Confirmación, Eucaristía, Reconciliación, Unción de los enfermos, Orden sacerdotal y Matrimonio.'},
{q:'¿De qué color es el Tiempo Ordinario?',a:'Verde',o:['Morado','Blanco','Rojo'],por:'El verde simboliza la esperanza y el crecimiento. «Ordinario» viene de «ordinal»: semanas numeradas.'},
{q:'¿Qué pasa con el Gloria en Adviento y Cuaresma?',a:'No se dice',o:['Se dice más largo','Se canta de rodillas','Solo se dice el domingo'],por:'Son tiempos de espera y penitencia; el Gloria se reserva para la alegría de la fiesta.'},
{q:'¿Cuándo se reza el Credo en la Misa?',a:'Los domingos y en las solemnidades',o:['Todos los días','Solo en Navidad','Solo en Semana Santa'],por:'En las Misas de semana normalmente no se dice.'},
{q:'¿Qué parte de la Misa termina con el «gran Amén»?',a:'La Plegaria Eucarística',o:['El Gloria','La homilía','La oración de los fieles'],por:'Al final de la doxología «Por Cristo, con él y en él…».'},
{q:'¿Cuándo nos damos la paz?',a:'Después del Padre Nuestro y antes de la comunión',o:['Al inicio de la Misa','Antes del Evangelio','Al terminar la Misa'],por:'Es un gesto de reconciliación antes de recibir a Cristo.'},
{q:'¿Para qué sirve el silencio después de «Oremos»?',a:'Para presentar a Dios nuestras intenciones personales',o:['Para esperar que termine el canto','Para revisar el misal','Para saludar a los vecinos'],por:'De ahí viene el nombre de «colecta»: recoge las intenciones.'},
{q:'¿Qué es el Triduo Pascual?',a:'Desde la Misa del Jueves Santo por la tarde hasta el Domingo de Pascua',o:['Los tres domingos de Adviento','Los tres días de Navidad','El Miércoles de Ceniza'],por:'Es el centro de todo el año litúrgico.'},
{q:'¿A quién representa el altar?',a:'A Cristo',o:['Solo al sacerdote','A los apóstoles','Al pueblo'],por:'Por eso se besa, se inciensa y no se usa para otros fines.'},
{q:'¿Qué hacemos con las manos al recibir la comunión en la mano?',a:'Una sobre otra, abiertas, y consumimos allí mismo',o:['La tomamos con los dedos y la guardamos','La tomamos y nos vamos al banco','Cerramos el puño'],por:'Se consume en presencia del ministro. Otra opción permitida es recibirla en la lengua.'}
];
const GLOS=[
{t:'Misa',d:'Celebración de la Eucaristía. La palabra viene del latín «missa» (envío), de la despedida «Ite, missa est».'},
{t:'Eucaristía',d:'Del griego «acción de gracias». Sacramento en que Cristo hace presente su sacrificio y se nos da como alimento: su Cuerpo y su Sangre bajo las apariencias del pan y del vino.'},
{t:'Liturgia',d:'Del griego «obra pública»; es la oración oficial de la Iglesia, donde Cristo mismo ora con su Cuerpo.'},
{t:'Sacramento',d:'Signo visible instituido por Cristo que da la gracia que significa. Son siete.'},
{t:'Presencia real',d:'Cristo está verdadera, real y sustancialmente presente en la Eucaristía, no solo como símbolo.'},
{t:'Transubstanciación',d:'Término teológico: la sustancia del pan y del vino se convierte en la del Cuerpo y la Sangre de Cristo; permanecen las apariencias.'},
{t:'Altar',d:'Mesa del sacrificio y de la cena del Señor, centro de la iglesia; simboliza a Cristo.'},
{t:'Ambón',d:'Lugar desde donde se proclama la Palabra de Dios en la Misa.'},
{t:'Sagrario',d:'Lugar donde se reserva la Eucaristía. Una lamparita encendida indica que Jesús está presente.'},
{t:'Misal',d:'Libro con las oraciones y ritos de la Misa. El Leccionario contiene las lecturas y el Evangeliario los Evangelios.'},
{t:'Homilía',d:'Del griego «conversación»: explicación de la Palabra de Dios aplicada a la vida de hoy.'},
{t:'Amén',d:'Del hebreo: «así es», «estoy de acuerdo». Al decirlo hacemos nuestra la oración.'},
{t:'Aleluya',d:'Del hebreo: «alaben al Señor». Es una aclamación de alegría que se canta antes del Evangelio.'},
{t:'Hosanna',d:'Del hebreo: «sálvanos, por favor». Se hizo grito de alabanza, como en la entrada de Jesús a Jerusalén.'},
{t:'Kyrie',d:'Del griego: «Señor». Aclamación «Señor, ten piedad» al comienzo de la Misa.'},
{t:'Colecta',d:'Primera oración del sacerdote; «recoge» las intenciones de todos.'},
{t:'Prefacio',d:'Oración de alabanza que abre la Plegaria Eucarística y cambia según el tiempo litúrgico.'},
{t:'Epíclesis',d:'Invocación al Espíritu Santo para que convierta el pan y el vino en el Cuerpo y la Sangre de Cristo.'},
{t:'Consagración',d:'Momento en que, por las palabras de Cristo y la acción del Espíritu, el pan y el vino se hacen su Cuerpo y su Sangre.'},
{t:'Memorial (anámnesis)',d:'No es solo recordar: es hacer presente el acontecimiento. En la Misa se hace presente la entrega de Cristo.'},
{t:'Doxología',d:'Fórmula de alabanza a la Trinidad, como «Por Cristo, con él y en él…» o «Gloria al Padre…».'},
{t:'Patena',d:'Plato sobre el que se coloca la hostia.'},
{t:'Cáliz',d:'Copa en la que se consagra el vino que se hace la Sangre de Cristo.'},
{t:'Corporal',d:'Paño cuadrado blanco que se extiende sobre el altar y sostiene la patena y el cáliz.'},
{t:'Hostia',d:'Del latín «víctima, ofrenda». Es el pan sin levadura que se consagra.'},
{t:'Casulla',d:'Vestidura exterior del sacerdote; su color depende del tiempo litúrgico.'},
{t:'Alba',d:'Túnica blanca que recuerda el vestido del bautismo.'},
{t:'Estola',d:'Tira de tela que lleva el sacerdote o el diácono; símbolo de su ministerio.'},
{t:'Genuflexión',d:'Gesto de rodillas al suelo (la derecha) ante el Santísimo Sacramento en el sagrario.'},
{t:'Diácono',d:'Ministro ordenado que proclama el Evangelio, sirve en el altar y puede predicar.'},
{t:'Acólito',d:'Servidor del altar (por ejemplo, un monaguillo).'},
{t:'Incienso',d:'Humo aromático que simboliza la oración que sube a Dios (Salmo 141, 2).'},
{t:'Cirio pascual',d:'Vela grande que se enciende en Pascua; simboliza a Cristo resucitado, luz del mundo.'},
{t:'Triduo Pascual',d:'Desde la Misa de la Cena del Señor (Jueves Santo por la tarde) hasta las vísperas del Domingo de Pascua: la pasión, muerte y resurrección de Jesús.'},
{t:'Tiempo Ordinario',d:'De «ordinal», no de «común»: son las semanas numeradas fuera de Adviento, Navidad, Cuaresma y Pascua.'},
{t:'Domingo de precepto',d:'Los católicos están llamados a participar en la Misa los domingos y días de fiesta de guardar.'},
{t:'Ayuno eucarístico',d:'Una hora sin comer ni beber (salvo agua y medicinas) antes de comulgar.'},
{t:'Viático',d:'Comunión que se da a quien está en peligro de muerte; significa «provisión para el camino».'},
{t:'Comunión espiritual',d:'Deseo sincero de recibir a Cristo cuando no se puede comulgar sacramentalmente.'},
{t:'Solemnidad, fiesta y memoria',d:'Grados de importancia de una celebración: la solemnidad es la mayor; luego la fiesta y la memoria.'},
{t:'Octava',d:'Ocho días de celebración continua de una gran fiesta, como la de Pascua o Navidad.'},
{t:'Vigilia',d:'Celebración que se hace en la noche anterior a una fiesta, como la Vigilia Pascual.'},
{t:'Credo',d:'Del latín «creo». Resume la fe de la Iglesia en la Trinidad. Hay dos credos: el Niceno-Constantinopolitano, más largo, que viene de los concilios de Nicea (325) y Constantinopla (381) y es el que se proclama en la Misa de los domingos y solemnidades; y el Símbolo de los Apóstoles, más breve y antiguo, que se reza en el Rosario y puede usarse en la Misa en su lugar, sobre todo en Cuaresma y Pascua. Los dos dicen la misma fe. Ambos están completos en Orar › Oraciones.'}
];
const ORACIONES=[
{id:'cruz',n:'Señal de la Cruz',t:'Por la señal de la santa cruz,\nde nuestros enemigos líbranos, Señor, Dios nuestro.\nEn el nombre del Padre, y del Hijo, y del Espíritu Santo. Amén.',m:'Es la primera y la última oración de la Misa. Al hacerla recordamos que somos bautizados y que Cristo nos salvó con su cruz.'},
{id:'padre',n:'Padre Nuestro',t:'Padre nuestro, que estás en el cielo,\nsantificado sea tu nombre;\nvenga a nosotros tu reino;\nhágase tu voluntad\nen la tierra como en el cielo.\nDanos hoy nuestro pan de cada día;\nperdona nuestras ofensas,\ncomo también nosotros perdonamos\na los que nos ofenden;\nno nos dejes caer en la tentación,\ny líbranos del mal. Amén.',m:'Tiene siete peticiones: las tres primeras son para Dios (su nombre, su reino, su voluntad) y las cuatro últimas para nosotros (pan, perdón, no caer, ser librados del mal). Algunas conferencias episcopales usan «no nos dejes caer en la tentación», otras «no nos induzcas»: pequeñas variantes según el país.'},
{id:'ave',n:'Ave María',t:'Dios te salve, María, llena eres de gracia,\nel Señor es contigo;\nbendita tú eres entre todas las mujeres,\ny bendito es el fruto de tu vientre, Jesús.\nSanta María, Madre de Dios,\nruega por nosotros, pecadores,\nahora y en la hora de nuestra muerte. Amén.',m:'La primera parte une el saludo del ángel Gabriel (Lucas 1, 28) y el de Isabel (Lucas 1, 42). La segunda es la súplica de la Iglesia a María.'},
{id:'vensp',n:'Ven, Espíritu Santo',t:'Ven, Espíritu Santo,\nllena los corazones de tus fieles\ny enciende en ellos el fuego de tu amor.\nV. Envía tu Espíritu y serán creadas todas las cosas.\nR. Y renovarás la faz de la tierra.\n\nOremos: Oh Dios, que has instruido los corazones de tus fieles con la luz del Espíritu Santo, concédenos que, guiados por el mismo Espíritu, sintamos rectamente y gocemos siempre de sus consuelos. Por Cristo, nuestro Señor. Amén.',m:'Se reza al empezar el Encuentro con Cristo, la oración personal o el estudio: pedimos al Espíritu que ilumine la mente, mueva la voluntad y encienda el corazón.'},
{id:'actos',n:'Actos de fe, esperanza y caridad',t:'Después de invocar al Espíritu Santo, haz con tus propias palabras tres actos breves:\n\nFe: dile a Jesús que crees que está aquí y que te escucha.\nEsperanza: dile que confías en Él y en lo que te promete.\nCaridad: dile que lo amas, y en Él a los demás.\n\nPuede ser tan sencillo como:\n«Creo, Jesús, espero en ti y te amo».',m:'No es una fórmula para memorizar, sino una guía para orar de forma libre, desde el corazón. Fe, esperanza y caridad son las virtudes que nos unen directamente a Dios; por eso son un buen comienzo para toda oración. Incluso esa frase tan breve ya es una oración muy profunda.'},
{id:'gloriah',n:'Gloria (himno de la Misa)',t:'Gloria a Dios en el cielo,\ny en la tierra paz a los hombres que ama el Señor.\nPor tu inmensa gloria te alabamos,\nte bendecimos, te adoramos,\nte glorificamos, te damos gracias,\nSeñor Dios, Rey celestial,\nDios Padre todopoderoso.\nSeñor, Hijo único, Jesucristo.\nSeñor Dios, Cordero de Dios, Hijo del Padre;\ntú que quitas el pecado del mundo,\nten piedad de nosotros;\ntú que quitas el pecado del mundo,\natiende nuestra súplica;\ntú que estás sentado a la derecha del Padre,\nten piedad de nosotros;\nporque solo tú eres Santo,\nsolo tú Señor,\nsolo tú Altísimo, Jesucristo,\ncon el Espíritu Santo\nen la gloria de Dios Padre. Amén.',m:'Se canta o se reza los domingos (salvo Adviento y Cuaresma), en solemnidades y fiestas, después del «Señor, ten piedad». Empieza con el canto de los ángeles en Belén.'},
{id:'credon',n:'Credo de la Misa (Niceno-Constantinopolitano)',t:'Creo en un solo Dios,\nPadre todopoderoso,\nCreador del cielo y de la tierra,\nde todo lo visible y lo invisible.\nCreo en un solo Señor, Jesucristo,\nHijo único de Dios,\nnacido del Padre antes de todos los siglos:\nDios de Dios, Luz de Luz,\nDios verdadero de Dios verdadero,\nengendrado, no creado,\nde la misma naturaleza del Padre,\npor quien todo fue hecho;\nque por nosotros, los hombres,\ny por nuestra salvación bajó del cielo,\n(aquí todos se inclinan)\ny por obra del Espíritu Santo\nse encarnó de María, la Virgen,\ny se hizo hombre;\ny por nuestra causa fue crucificado\nen tiempos de Poncio Pilato;\npadeció y fue sepultado,\ny resucitó al tercer día, según las Escrituras,\ny subió al cielo,\ny está sentado a la derecha del Padre;\ny de nuevo vendrá con gloria\npara juzgar a vivos y muertos,\ny su reino no tendrá fin.\nCreo en el Espíritu Santo, Señor y dador de vida,\nque procede del Padre y del Hijo,\nque con el Padre y el Hijo\nrecibe una misma adoración y gloria,\ny que habló por los profetas.\nCreo en la Iglesia,\nque es una, santa, católica y apostólica.\nConfieso que hay un solo bautismo\npara el perdón de los pecados.\nEspero la resurrección de los muertos\ny la vida del mundo futuro. Amén.',m:'Es el Credo que se proclama de pie en la Misa de los domingos y solemnidades, después de la homilía. En algunas Misas se usa en su lugar el Símbolo de los Apóstoles.'},
{id:'santo',n:'Santo (Sanctus)',t:'Santo, Santo, Santo es el Señor,\nDios del universo.\nLlenos están el cielo y la tierra de tu gloria.\nHosanna en el cielo.\nBendito el que viene en nombre del Señor.\nHosanna en el cielo.',m:'Se canta al terminar el prefacio, uniéndonos a los ángeles (Isaías 6, 3) y a la multitud que recibió a Jesús en Jerusalén (Mateo 21, 9).'},
{id:'rcinv',n:'Invocación del Regnum Christi',t:'¡Cristo, Rey nuestro!\n— ¡Venga tu Reino!',m:'Es el lema y la jaculatoria del Regnum Christi, tomado del Padre Nuestro. Pedimos que Cristo reine en nuestro corazón, en la familia, en el trabajo y en la sociedad. Se dice al empezar y al terminar la oración y el Encuentro.'},
{id:"crrey",n:"Oración a Cristo Rey",t:"Oh, Cristo Jesús, te reconozco por rey universal. Todo cuanto existe ha sido creado por ti. Ejerce sobre mí todos tus derechos. Renuevo mis promesas del bautismo renunciando a Satanás, a sus seducciones y a sus obras, y prometo vivir como buen cristiano. Muy en particular me comprometo a hacer triunfar, según mis medios, los derechos de Dios y de tu Iglesia. Jesucristo, te ofrezco mis pobres acciones para obtener que todos los corazones reconozcan y vivan tu mensaje de paz, de justicia y de amor.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 91. Cristo Rey es la fiesta titular del Regnum Christi.",g:"rc"},
{id:"apost",n:"Oración del apóstol",t:"Señor, que nos has dado la gracia de pertenecer a tu Iglesia y de participar en ella de tu misión de salvar a los hombres, ayúdanos a conocerte mejor, a seguirte más de cerca y darte a conocer a todos los hombres. Inspíranos valor y entusiasmo, para hacernos amigos de todos aquellos con quienes nos encontremos y podamos acercarlos a ti. Nunca permitas que te ofendamos en palabras o acciones.\n\nMantennos siempre cerca de ti y haz que seamos vigorosos miembros de tu Iglesia. Fortalece y acrecienta tu vida en nosotros, para que cuanto hagamos sea hecho contigo y para ti.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 81.",g:"rc"},
{id:"laicos",n:"Oración de los laicos",t:"Señor Dios nuestro, Tú que has puesto como fermento en el mundo la fuerza del Evangelio, concédenos a los llamados a vivir en medio de los afanes temporales que, encendidos por el fuego del Espíritu, nos entreguemos apasionadamente a la misión de hacer presente el Reino de Cristo en el mundo, para que Él sea todo, en todos. Por Cristo nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 81.",g:"rc"},
{id:"rcrenov",n:"Por la renovación del Regnum Christi",t:"Jesucristo, reunidos en tu nombre como familia espiritual, nos ponemos en tu presencia.\nTú te has dignado revelarnos el misterio del amor que arde en tu Corazón por todos los hombres y tu deseo de reinar en nuestras almas y en la sociedad.\nNos sentimos llamados a conocer mejor el don del Regnum Christi para que sea fecundo en nuestras vidas.\nTe pedimos que envíes tu Espíritu: que sea luz para comprender y vivir con la mente y el corazón nuestro carisma y que estemos siempre prontos a dar una respuesta a las necesidades de la Iglesia y del mundo como apóstoles de tu Reino.\nA ejemplo de María, queremos vivir nuestro camino descubriendo y acogiendo la acción de tu Espíritu aceptando tu designio con fe y alabanza por las grandes obras que has hecho y que sigues haciendo entre nosotros.\nJesucristo, Tú eres el centro de nuestras vidas. Con un amor renovado, hoy te decimos: «Cristo Rey nuestro, ¡Venga tu Reino!»",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 79.",g:"rc"},
{id:"rccom",n:"Por la comunión del Regnum Christi",t:"Señor Jesús,\npor el don del bautismo somos hijos de Dios\nreunidos en la Trinidad y en la comunión de la Iglesia.\nTú nos has llamado al Regnum Christi,\nuna familia espiritual que quiere llevar tu amor a todos los hombres.\nIlumina mis ojos para ver el don que cada persona es.\nAbre mis oídos para escuchar las necesidades del otro.\nPon en mi boca la Palabra para encontrarme con mis hermanos y hermanas.\nVive en mi corazón para unirnos en ideales, propósitos y esfuerzos,\npara que trabajemos juntos por hacer presente tu Reino.\nHazme consciente de que la comunión es misionera\ny de que la misión es para la comunión.\nRecuérdame, cada vez que lo olvido:\nsomos un solo Cuerpo en Cristo y la mayor llamada es\namarnos los unos a los otros como tú nos has amado\npara que el mundo pueda conocer tu amor.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 80.",g:"rc"},
{id:"renov",n:"Renovación de la asociación al Regnum Christi",t:"Señor, Tú me has llamado a vivir conscientemente mi vocación bautismal a la santidad y al apostolado según el carisma del Regnum Christi, para entregarme a Cristo desde mi estado y condición de vida a fin de que Él reine en mi corazón y en la sociedad. Por eso deseo renovar mi pertenencia al Regnum Christi como miembro de esta familia espiritual. Para ello me comprometo a:\n• Crecer en la amistad con Cristo desarrollando la vida de gracia a través de la oración y los sacramentos.\n• Vivir las virtudes evangélicas de la pobreza, la obediencia filial y la pureza en pensamientos y acciones.\n• Cumplir con amor y honestidad los deberes propios de mi estado de vida como un servicio a Dios y a los demás.\n• Empeñarme en mi formación integral y forjar mi liderazgo cristiano.\n• Emprender y participar en iniciativas apostólicas.\n• Profesar un amor fiel y operante a la santa Iglesia, al papa y a los demás obispos.\n• Ofrecer generosamente mi oración, talentos, tiempo y haberes para colaborar en la misión del Regnum Christi al servicio de la Iglesia.\n\nMe toca a mí, de mí también depende, que tus palabras, Señor, no se pierdan.\nMe toca a mí que tu mensaje de salvación llegue a los hombres.\nMe toca a mí vivir de tal manera tu palabra que, cuantos me vean te reconozcan y te den gloria y se sientan impulsados por tu gracia a participar de la fe de la Iglesia y a dar testimonio vivo de ella.\nMe toca a mí encarnar el carisma del Regnum Christi para cumplir esta misión en la Iglesia y en el mundo. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 70, según el Ritual del Regnum Christi. Se renueva cada año al terminar la Misa de Cristo Rey, pero puede rezarse a menudo, solo o en equipo.",g:"rc"},
{id:"rcfin",n:"Conclusión de las oraciones",t:"Guía: ¡Cristo, Rey nuestro!\nTodos: ¡Venga tu Reino!\nGuía: Virgen prudentísima, María, Madre de la Iglesia (o bien: Madre dolorosa; o bien: Reina de los Apóstoles),\nTodos: ruega por nosotros.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 95. Así terminan las oraciones y el Encuentro con Cristo en el Regnum Christi.",g:"rc"},
{id:"tomad",n:"Acto de entrega (San Ignacio de Loyola)",t:"Toma, Señor, y recibe toda mi libertad, mi memoria, mi entendimiento y toda mi voluntad, todo lo que tengo y poseo. Tú me lo diste; a ti, Señor, lo torno; todo es tuyo, dispón a toda tu voluntad. Dame tu amor y gracia, que esto me basta.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 91. Es la oración de san Ignacio en sus Ejercicios Espirituales (n. 234): la entrega total del apóstol.",g:"com"},
{id:'gloria',n:'Gloria al Padre',t:'Gloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\ny por los siglos de los siglos. Amén.',m:'Pequeña alabanza a la Trinidad. Se reza al final de cada decena del Rosario y de los salmos.'},
{id:'credoap',n:'Credo (Símbolo de los Apóstoles)',t:'Creo en Dios, Padre todopoderoso,\nCreador del cielo y de la tierra.\nCreo en Jesucristo, su único Hijo, nuestro Señor,\nque fue concebido por obra y gracia del Espíritu Santo,\nnació de santa María Virgen,\npadeció bajo el poder de Poncio Pilato,\nfue crucificado, muerto y sepultado,\ndescendió a los infiernos,\nal tercer día resucitó de entre los muertos,\nsubió a los cielos\ny está sentado a la derecha de Dios, Padre todopoderoso.\nDesde allí ha de venir a juzgar a vivos y muertos.\nCreo en el Espíritu Santo,\nla santa Iglesia católica,\nla comunión de los santos,\nel perdón de los pecados,\nla resurrección de la carne\ny la vida eterna. Amén.',m:'Es el credo más breve y antiguo. En la Misa dominical normalmente se proclama el Credo Niceno-Constantinopolitano, más largo; el de los Apóstoles se usa en el Rosario y como alternativa.'},
{id:'confieso',n:'Yo confieso (Confiteor)',t:'Yo confieso ante Dios todopoderoso\ny ante ustedes, hermanos,\nque he pecado mucho\nde pensamiento, palabra, obra y omisión.\nPor mi culpa, por mi culpa, por mi gran culpa.\nPor eso ruego a santa María, siempre Virgen,\na los ángeles, a los santos\ny a ustedes, hermanos,\nque intercedan por mí ante Dios, nuestro Señor.',m:'Se reza en el acto penitencial. «Omisión» es lo bueno que dejamos de hacer. El golpe de pecho acompaña a «por mi culpa».'},
{id:'contri',n:'Acto de contrición',t:'Señor mío, Jesucristo,\nDios y hombre verdadero,\nCreador, Padre y Redentor mío:\npor ser Tú quien eres, bondad infinita,\ny porque te amo sobre todas las cosas,\nme pesa de todo corazón haberte ofendido.\nAyudado de tu divina gracia,\npropongo firmemente nunca más pecar,\nconfesarme y cumplir la penitencia que me fuere impuesta.\nAmén.',m:'Se reza en la confesión y por la noche. Contrición perfecta es el dolor por amor a Dios; tiene como fruto el propósito de enmendarse. Versión breve: «Jesús, ten piedad de mí, que soy pecador».'},
{id:"angelus",n:"Ángelus",t:"V. El ángel del Señor anunció a María.\nR. Y concibió del Espíritu Santo.\nDios te salve, María…\nV. He aquí la esclava del Señor.\nR. Hágase en mí según tu palabra.\nDios te salve, María…\nV. Y el Verbo se hizo carne.\nR. Y habitó entre nosotros.\nDios te salve, María…\nV. Ruega por nosotros, Santa Madre de Dios,\nR. para que seamos dignos de las promesas de Cristo.\n\nOremos: Te pedimos, Señor, que infundas tu gracia en nuestras mentes, para que los que hemos conocido por el mensaje del ángel el misterio de la encarnación de tu Hijo, seamos conducidos a la gloria de la resurrección, por los méritos de su cruz y pasión. Por Jesucristo, nuestro Señor. Amén.\n\nGloria al Padre… (tres veces)\n\nÁngel del Señor, que eres mi custodio: puesto que la providencia soberana me encomendó a ti, ilumíname, guárdame, rígeme y gobiérname en este día. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 31. Se reza a mediodía todo el año, excepto en el tiempo pascual. En el Regnum Christi se acostumbra terminar encomendándose al Ángel de la guarda.",g:"dia"},
{id:"regina",n:"Regina Coeli (en Pascua)",t:"V. Alégrate, Reina del cielo, aleluya.\nR. Porque aquel a quien mereciste llevar en tu seno, aleluya.\nV. Ha resucitado como lo predijo, aleluya.\nR. Intercede por nosotros ante Dios, aleluya.\nV. Gózate y alégrate, María Virgen, aleluya.\nR. Porque en verdad el Señor ha resucitado, aleluya.\n\nOremos: Oh, Dios, que has llenado de alegría al mundo con la resurrección de Jesucristo, tu Hijo, nuestro Señor, concédenos por la intercesión de su madre la Virgen María, el llegar a poseer la dicha de la vida inmortal. Por Jesucristo, nuestro Señor. Amén.\n\nGloria al Padre… (tres veces)",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 32. Sustituye al Ángelus desde el Domingo de Pascua hasta el mediodía del sábado de Pentecostés.",g:"dia"},
{id:'salve',n:'Salve',t:'Dios te salve, Reina y Madre de misericordia,\nvida, dulzura y esperanza nuestra; Dios te salve.\nA ti llamamos los desterrados hijos de Eva;\na ti suspiramos, gimiendo y llorando\nen este valle de lágrimas.\nEa, pues, Señora, abogada nuestra,\nvuelve a nosotros esos tus ojos misericordiosos;\ny después de este destierro,\nmuéstranos a Jesús, fruto bendito de tu vientre.\n¡Oh clemente, oh piadosa, oh dulce Virgen María!\nRuega por nosotros, santa Madre de Dios,\npara que seamos dignos de alcanzar\nlas promesas de nuestro Señor Jesucristo. Amén.',m:'Se reza al terminar el Rosario. Es una oración antigua de súplica a María, nuestra madre y abogada.'},
{id:'letanias',n:'Letanías de la Virgen (Lauretanas)',t:'Señor, ten piedad.\nCristo, ten piedad.\nSeñor, ten piedad.\nCristo, óyenos.\nCristo, escúchanos.\n\nDios, Padre celestial, — ten piedad de nosotros.\nDios, Hijo, Redentor del mundo, — ten piedad de nosotros.\nDios, Espíritu Santo, — ten piedad de nosotros.\nSantísima Trinidad, un solo Dios, — ten piedad de nosotros.\n\n(A cada invocación se responde: ruega por nosotros.)\nSanta María,\nSanta Madre de Dios,\nSanta Virgen de las Vírgenes,\nMadre de Cristo,\nMadre de la Iglesia,\nMadre de la misericordia,\nMadre de la divina gracia,\nMadre de la esperanza,\nMadre purísima,\nMadre castísima,\nMadre siempre virgen,\nMadre inmaculada,\nMadre amable,\nMadre admirable,\nMadre del buen consejo,\nMadre del Creador,\nMadre del Salvador,\nVirgen prudentísima,\nVirgen digna de veneración,\nVirgen digna de alabanza,\nVirgen poderosa,\nVirgen clemente,\nVirgen fiel,\nEspejo de justicia,\nTrono de la sabiduría,\nCausa de nuestra alegría,\nVaso espiritual,\nVaso digno de honor,\nVaso de insigne devoción,\nRosa mística,\nTorre de David,\nTorre de marfil,\nCasa de oro,\nArca de la Alianza,\nPuerta del cielo,\nEstrella de la mañana,\nSalud de los enfermos,\nRefugio de los pecadores,\nConsuelo de los migrantes,\nConsoladora de los afligidos,\nAuxilio de los cristianos,\nReina de los Ángeles,\nReina de los Patriarcas,\nReina de los Profetas,\nReina de los Apóstoles,\nReina de los Mártires,\nReina de los Confesores,\nReina de las Vírgenes,\nReina de todos los Santos,\nReina concebida sin pecado original,\nReina asunta a los cielos,\nReina del santísimo Rosario,\nReina de la familia,\nReina de la paz,\n\nCordero de Dios, que quitas el pecado del mundo, — perdónanos, Señor.\nCordero de Dios, que quitas el pecado del mundo, — escúchanos, Señor.\nCordero de Dios, que quitas el pecado del mundo, — ten misericordia de nosotros.\n\nV. Ruega por nosotros, santa Madre de Dios.\nR. Para que seamos dignos de alcanzar las promesas de nuestro Señor Jesucristo.\n\nOremos: Te rogamos, Señor Dios nuestro, que nos concedas gozar de continua salud de alma y cuerpo, y que, por la gloriosa intercesión de la bienaventurada siempre Virgen María, seamos librados de las tristezas presentes y gocemos de las alegrías eternas. Por Cristo nuestro Señor. Amén.',m:'Letanías de Loreto, aprobadas por el papa Sixto V en 1587. Se rezan al terminar el Rosario, después de la Salve. Están al día: en 2020 el papa Francisco añadió «Madre de la misericordia», «Madre de la esperanza» y «Consuelo de los migrantes»; también incluyen «Madre de la Iglesia» y «Reina de la familia», que añadió san Juan Pablo II.'},
{id:'madregr',n:'María, Madre de gracia',t:'María, Madre de gracia, Madre de piedad y de misericordia,\ndefiéndenos de nuestros enemigos\ny ampáranos ahora y en la hora de nuestra muerte. Amén.',m:'Jaculatoria muy rezada en Venezuela y América Latina después del Gloria de cada misterio del Rosario, junto al «Oh Jesús mío». Es opcional.'},
{id:'simeon',n:'Cántico de Simeón (Nunc dimittis)',t:'Antífona: Sálvanos, Señor, despiertos, protégenos mientras dormimos, para que velemos con Cristo y descansemos en paz.\n\nAhora, Señor, según tu promesa,\npuedes dejar a tu siervo irse en paz.\nPorque mis ojos han visto a tu Salvador,\na quien has presentado ante todos los pueblos:\nluz para alumbrar a las naciones\ny gloria de tu pueblo Israel.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén.\n\nAntífona: Sálvanos, Señor, despiertos, protégenos mientras dormimos, para que velemos con Cristo y descansemos en paz.',m:'Son las palabras del anciano Simeón cuando tomó en brazos al Niño Jesús en el Templo (Lucas 2, 29-32). La Iglesia las reza cada noche en Completas, la última hora de la Liturgia de las Horas: como Simeón, terminamos el día en paz porque hemos visto a Jesús.'},
{id:'visita',n:'Visita, Señor, esta habitación',t:'Visita, Señor, esta habitación:\naleja de ella las insidias del enemigo;\nque tus santos ángeles habiten en ella\ny nos guarden en paz,\ny que tu bendición permanezca siempre con nosotros.\nPor Jesucristo, nuestro Señor. Amén.',m:'Oración final de Completas, muy antigua. Pide a Dios que proteja la casa durante la noche y que sus ángeles nos cuiden mientras dormimos.'},
{id:"noche",n:"Oraciones de la noche (Regnum Christi)",t:"En el nombre del Padre, del Hijo y del Espíritu Santo. Amén.\n\nBalance\nSeñor y Dios mío, que eres todo bondad y misericordia infinita, te doy gracias con todo mi corazón por los innumerables beneficios que me has concedido, muy especialmente por haberme creado, redimido, llamado a la fe católica y elegido para hacer presente el Reino de Cristo entre mis hermanos, por haberme librado de tantos peligros de alma y cuerpo. Dígnate, Señor, iluminar mi entendimiento para que conozca mis culpas y concédeme la gracia de un verdadero dolor y de una sincera enmienda.\n\n(Unos momentos en silencio: mira el bien de hoy y la acción de Dios, pide perdón por el mal y confíate a su gracia para mañana.)\n\nAntífona\nSálvanos, Señor, despiertos, protégenos mientras dormimos, para que velemos con Cristo y descansemos en paz.\n\nNunc dimittis\nAhora, Señor, según tu promesa,\npuedes dejar a tu siervo irse en paz.\nPorque mis ojos han visto a tu Salvador,\na quien has presentado ante todos los pueblos:\nluz para alumbrar a las naciones\ny gloria de tu pueblo Israel.\n\nGloria al Padre…\n\nConclusión\nEl Señor todopoderoso nos conceda una noche tranquila y una muerte santa. Amén.\n\nSalve",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 46. También puedes rezar las Completas de la Liturgia de las Horas.",g:"dia"},
{id:'amparo',n:'Bajo tu amparo',t:'Bajo tu amparo nos acogemos,\nsanta Madre de Dios;\nno deseches las súplicas\nque te dirigimos en nuestras necesidades,\nantes bien, líbranos de todo peligro,\noh Virgen gloriosa y bendita.',m:'Es la oración a la Virgen más antigua que se conoce (hacia el siglo III). Se puede rezar al final de Completas en lugar de la Salve, o en cualquier momento de necesidad.'},
{id:"levant",n:"Al levantarse",t:"¡Cristo, Rey nuestro!\n— ¡Venga tu Reino!\n\n(Padre Nuestro y Ave María)\n\nSeñor y Padre mío, inspira mis pensamientos, palabras y acciones, y acompáñalos con tu ayuda, para que todas mis actividades comiencen y terminen según tu voluntad y por amor a ti. Por Jesucristo, nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 25. Levantarse es volver a nacer: un momento para elevar la mente y el corazón al Señor y pedirle que baje a nuestra vida.",g:"dia"},
{id:"ofrec",n:"Ofrecimiento de obras (Regnum Christi)",t:"En el nombre del Padre y del Hijo y del Espíritu Santo. Amén.\n\nOración al Padre\nCreo en ti, Dios mío, porque eres la verdad misma. Espero en ti, porque eres la misericordia infinita. Te amo sobre todas las cosas porque eres infinitamente amable y porque a ti solo debo amarte con todo mi corazón, con toda mi alma y con todas mis fuerzas. Te doy gracias, Padre, por haberme concedido un nuevo día para darte gloria y hacer presente tu reino. Amén.\n\nOración a Jesucristo\nSeñor Jesús:\nTe entrego mis manos para hacer tu trabajo.\nTe entrego mis pies para seguir tu camino.\nTe entrego mis ojos para ver como tú ves.\nTe entrego mi lengua para hablar tus palabras.\nTe entrego mi mente para que tú pienses en mí.\nTe entrego mi espíritu para que tú ores en mí.\nSobre todo, te entrego mi corazón para que en mí ames a tu Padre y a todos los hombres.\nTe entrego todo mi ser para que crezcas tú en mí, para que seas tú, Cristo, quien viva, trabaje y ore en mí. Amén.\n\nOración al Espíritu Santo\nEspíritu Santo, dulce huésped y consolador de mi alma, guía y artífice de nuestra transformación en Cristo: ilumina mi entendimiento para conocer tu voluntad; inflama mi corazón para amarla con pasión y concédeme la fortaleza necesaria para cumplirla como tú me pides. Dame, Espíritu de amor, la gracia de corresponder fielmente a tus santas inspiraciones.\n\nOración a la Santísima Virgen\nMadre mía, vengo ante ti en este nuevo día a consagrarte todos mis pensamientos, palabras y obras y a pedirte tu bendición para mí, mis seres queridos y todas las personas que has puesto en mi camino. Concédeme un corazón de apóstol del Reino e imitar la vida de oración, de obediencia, de humildad, de fidelidad, de sacrificio y de sencillez que compartiste con tu Hijo, nuestro hermano y Señor. Dile a Jesús, oh, Madre, que quiero servirle en el Regnum Christi para hacer presente su Reino entre los hombres.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 26. Al despertar ofrecemos el día. Luego, unos minutos de «examen de previsión»: revisar la agenda con Dios, ofrecerle las actividades y renovar el propósito de vivir en Cristo. El libro pide mantener siempre la Oración a Jesucristo, común a todos los miembros del Regnum Christi.",g:"dia"},
{id:"ofrecrm",n:"Ofrecimiento breve (Red Mundial de Oración del Papa)",t:"Con María te ofrezco mi jornada\npor la misión de la Iglesia\ny por las intenciones de oración del Papa\ny de mi obispo para este mes.\nAmén.",m:"Ofrecimiento diario de la Red Mundial de Oración del Papa (antes Apostolado de la Oración), la obra pontificia que reza cada mes por las intenciones del Santo Padre. Útil cuando tienes poco tiempo.",g:"dia"},
{id:"comida",n:"Antes y después de comer",t:"Antes de comer\nGuía: En el nombre del Padre y del Hijo y del Espíritu Santo.\nTodos: Amén.\nGuía: Bendícenos, Señor, a nosotros y estos dones tuyos que vamos a tomar y que hemos recibido de tu generosidad. Por Jesucristo, nuestro Señor.\nTodos: Amén.\n\nDespués de comer\nGuía: Te damos gracias, Señor, por todos tus beneficios, a ti, que vives y reinas por los siglos de los siglos.\nTodos: Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 78.",g:"dia"},
{id:'guarda',n:'Ángel de la guarda',t:'Ángel de la guarda,\ndulce compañía,\nno me desampares\nni de noche ni de día.\nHasta que me pongas\nen paz y alegría\ncon todos los santos,\nJesús, José y María.',m:'Oración tradicional para los niños y para toda la familia, especialmente antes de dormir.'},
{id:"comesp",n:"Comunión espiritual",t:"Creo, Jesús mío, que estás presente en el Santísimo Sacramento. Te amo sobre todas las cosas y deseo recibirte en mi alma; pero, no pudiendo hacerlo sacramentalmente, ven al menos espiritualmente a mi corazón. Y como si ya te hubiese recibido, me abrazo y me uno todo a ti: no permitas que me separe de ti. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 45. Cuando no puedes visitar a Jesús en el Sagrario ni comulgar. Es tradición del Regnum Christi hacer una visita eucarística al llegar a un lugar con capilla.",g:"dia"},
{id:'anima',n:'Alma de Cristo (Anima Christi)',t:'Alma de Cristo, santifícame.\nCuerpo de Cristo, sálvame.\nSangre de Cristo, embriágame.\nAgua del costado de Cristo, lávame.\nPasión de Cristo, confórtame.\n¡Oh, buen Jesús!, óyeme.\nDentro de tus llagas, escóndeme.\nNo permitas que me aparte de ti.\nDel maligno enemigo, defiéndeme.\nEn la hora de mi muerte, llámame.\nY mándame ir a ti,\npara que con tus santos te alabe\npor los siglos de los siglos. Amén.',m:'Oración muy antigua, ideal para después de comulgar.'},
{id:'miseric',n:'Coronilla de la Divina Misericordia',t:'Empieza con: Padre Nuestro, Ave María y Credo.\n\nEn las cuentas grandes:\nPadre Eterno, te ofrezco el Cuerpo y la Sangre,\nel Alma y la Divinidad\nde tu amadísimo Hijo, nuestro Señor Jesucristo,\nen expiación de nuestros pecados y los del mundo entero.\n\nEn las diez cuentas pequeñas (cada decena):\nPor su dolorosa pasión,\nten misericordia de nosotros y del mundo entero.\n\nAl final (tres veces):\nSanto Dios, Santo Fuerte, Santo Inmortal,\nten piedad de nosotros y del mundo entero.',m:'Se reza tradicionalmente a las 3 p. m., la hora de la muerte de Jesús. Viene de las revelaciones de santa Faustina Kowalska.'},
{id:"miguel",n:"A san Miguel arcángel",t:"San Miguel, arcángel, defiéndenos en la lucha. Sé nuestro amparo contra la perversidad y las asechanzas del demonio: reprímalo Dios, te lo pedimos suplicantes. Y tú, príncipe del ejército del cielo, con el poder que Dios te ha conferido, arroja al infierno a Satanás y a los demás espíritus malignos que vagan por el mundo para la perdición de los hombres.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 80. Oración del papa León XIII.",g:"mom"},
{id:"hijos",n:"Por los hijos",t:"Señor, ilumina la mente de nuestros hijos para que conozcan el camino que tú has querido para ellos, para que te puedan dar gloria y alcancen la salvación. Sostenlos con tu fuerza, para que alienten en su vida los ideales de tu Reino. Ilumínanos también a nosotros, sus padres, para que les ayudemos a reconocer su vocación cristiana y a realizarla generosamente, colaborando con tus inspiraciones interiores. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 85.",g:"mom"},
{id:"dehijos",n:"Oración de los hijos (por los padres)",t:"Oh, Dios, que nos has mandado honrar padre y madre, escucha con benevolencia la oración que te dirigimos por ellos. Concédeles largos días de vida en la tierra, y consérvales la salud del cuerpo y del espíritu. Bendice sus fatigas y sus iniciativas. Recompénsales por todo lo que han hecho por mí. Inspírales el amor y la práctica de tu santa ley. Ayúdame a hacer todo lo que pueda por ellos. Y haz que después de haber gozado de su afecto en la tierra, tenga la alegría de vivir eternamente con ellos en el cielo. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 85.",g:"mom"},
{id:"enfermos",n:"Por los enfermos",t:"Tú quisiste, Señor, que tu Hijo unigénito soportara nuestras debilidades, para poner de manifiesto el valor de la enfermedad y la paciencia; escucha ahora las plegarias que te dirigimos por nuestros hermanos enfermos, y concede a cuantos se hallan sometidos al dolor, la aflicción o la enfermedad, la gracia de sentirse elegidos entre aquellos que tu Hijo ha llamado dichosos, y de saberse unidos a la pasión de Cristo para la redención del mundo. Te lo pedimos por Cristo nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 86.",g:"mom"},
{id:"sufren",n:"Por los que sufren",t:"Oh, Dios, refugio providente de los que sufren; escucha la oración que te dirigimos por ellos. Serena y conforta a los enfermos, a los ancianos y a los moribundos. Da a los que les cuidan sabiduría y paciencia, tacto y compasión. Inspírales los gestos que dan alivio, las palabras que iluminan y el amor que conforta. Te encomendamos los corazones desalentados, en rebeldía, desgarrados por la tentación, atormentados por la pasión, heridos o profanados por la maldad de los hombres. Pon dentro de nosotros, Señor, tu Espíritu de amor, de comprensión, de sacrificio, para que llevemos ayuda eficaz a todos aquellos que encontramos en nuestro camino sufriendo. Ayúdanos a responder a su llamada: es la tuya. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 86.",g:"mom"},
{id:"dificult",n:"En las dificultades de la vida",t:"Señor, haz que afrontemos con ánimo fuerte y sereno las dificultades, las obligaciones y las responsabilidades que tenemos y, consolados por ti, sepamos confortar a nuestros hermanos. Por Jesucristo, nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 87.",g:"mom"},
{id:"viaje",n:"Antes de un viaje",t:"Señor, que llenas todo lugar con tu presencia: acompáñame en este viaje, para que llegue a mi destino y vuelva a casa sano y salvo. Que mi viaje sea un anuncio de alegría a todos los que encuentre, un mensaje de esperanza, un testimonio de vida cristiana. Amén.\nEl auxilio divino permanezca siempre con nosotros. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 87.",g:"mom"},
{id:"difunto",n:"Por un difunto",t:"Señor, recuerda a N., a quien llamaste de este mundo a tu presencia; concédele que, así como ha compartido ya la muerte de Jesucristo, comparta también con Él la gloria de la resurrección, cuando Cristo haga surgir de la tierra a los muertos y transforme nuestro cuerpo frágil en cuerpo glorioso como el suyo. Por el mismo Cristo nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 87. En lugar de «N.» se dice el nombre de la persona.",g:"mom"},
{id:"buenamu",n:"Por la gracia de la buena muerte",t:"Oh, Dios, que nos has creado a imagen tuya y has entregado a tu Hijo a la muerte por nosotros, concédenos la gracia de vivir vigilando en oración, para que podamos salir sin pecado de este mundo y descansar con alegría en el regazo de tu misericordia. Por Cristo nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 88.",g:"mom"},
{id:"gracias",n:"Acción de gracias",t:"Oh, Dios, Padre de todos los dones, de quien viene cuanto somos y tenemos, enséñanos a reconocer los beneficios de tu amor y a amarte con todas las fuerzas de nuestro corazón. Te lo pedimos por Jesucristo, nuestro Señor. Amén.\n\nO bien:\nOh, Dios, fuente de todo bien, principio de nuestro existir y de nuestro obrar; recibe nuestro humilde agradecimiento por todos tus beneficios, y haz que al don de tu benevolencia corresponda el generoso empeño de nuestra vida al servicio de tu Reino. Por Jesucristo, nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 88.",g:"mom"},
{id:"crucif",n:"A Jesús crucificado",t:"Mírame, oh, mi amado y buen Jesús, postrado a los pies de tu santísima presencia. Te ruego con el mayor fervor que imprimas en mi corazón vivos sentimientos de fe, esperanza y caridad, verdadero dolor de mis pecados y propósito firmísimo de enmendarme. Mientras que yo, con todo el amor y compasión de mi alma, voy considerando tus cinco llagas, teniendo presente aquello que dijo de ti, oh, buen Jesús, el santo profeta David: «Han taladrado mis manos y mis pies, y se pueden contar todos mis huesos» (Sal 22,17-18).",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 89. Se suele rezar después de comulgar, mirando el crucifijo.",g:"com"},
{id:"clemente",n:"Oración universal (atribuida al papa Clemente XI)",t:"Creo, Señor, fortalece mi fe; espero, Señor, asegura mi esperanza; amo, Señor, inflama mi amor; me pesa, Señor, aumenta mi arrepentimiento.\nTe adoro como a primer principio, te deseo como a último fin, te alabo como a bienhechor perpetuo, te invoco como a defensor propicio.\nDirígeme con tu sabiduría, contenme con tu justicia, consuélame con tu clemencia, protégeme con tu poder.\nTe ofrezco, Señor, mis pensamientos para pensar en ti, mis palabras para hablar de ti, mis sufrimientos para padecerlos por ti.\nQuiero lo que tú quieres, lo quiero porque lo quieres, lo quiero como lo quieres, lo quiero en cuanto lo quieres.\nTe ruego Señor, que alumbres mi entendimiento, abrases mi voluntad, purifiques mi corazón, santifiques mi alma.\nLlore los pecados pasados, rechace las tentaciones futuras, corrija las inclinaciones viciosas, cultive las virtudes necesarias.\nConcédeme, Dios bueno, amor a ti, olvido de mí, celo del prójimo, desprecio del mundo.\nProcure obedecer a los superiores, atender a los inferiores, favorecer a los amigos, perdonar a los enemigos.\nVenza el deleite con la mortificación, la avaricia con la largueza, la ira con la mansedumbre, la tibieza con el fervor.\nHazme prudente en los consejos, constante en los peligros, paciente en las adversidades, humilde en las prosperidades.\nHaz, Señor, que sea en la oración, atento; en la comida, sobrio; en los deberes, diligente; en los propósitos, constante.\nQue procure tener inocencia interior, modestia exterior, conversación edificante, vida recta.\nQue me aplique con diligencia a domar la naturaleza, a corresponder a la gracia, a guardar tu ley, a merecer la salvación.\nAprenda de ti qué frágil es lo terreno, qué grande lo divino, qué breve lo temporal, qué duradero lo eterno.\nConcédeme que me prepare a la muerte, que tema el juicio, que evite el infierno, que obtenga el paraíso.\nPor Jesucristo, nuestro Señor. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 90.",g:"com"},
{id:"papa",n:"Por el Papa",t:"Oh, Jesús, rey y señor de la Iglesia: renuevo en tu presencia mi adhesión incondicional al papa, principio y fundamento visible de unidad en tu Iglesia. Creo firmemente que, por medio de él, tú nos gobiernas, enseñas y santificas. Cuida su vida, ilumina su inteligencia, fortalece su espíritu y concédenos que, en torno a él, tu Iglesia se conserve unida, firme en el creer y en el obrar, y sea así el fiel instrumento de tu redención. Amén.",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 91.",g:"com"},
{id:"vocac",n:"Por las vocaciones",t:"¡Oh, Jesús, pastor eterno de las almas! Dígnate mirar con ojos de misericordia a esta porción de tu grey amada. Señor, gemimos en la orfandad. Danos vocaciones. Danos sacerdotes y religiosos santos. Te lo pedimos por la intercesión de santa María de Guadalupe, tu dulce y santa madre. ¡Oh, Jesús, danos sacerdotes y almas consagradas, según tu corazón!",m:"Del libro de oración del Regnum Christi «Señor, enséñanos a orar» (SEO), p. 92.",g:"com"},
];
