const MANDAMIENTOS=[
{n:'1.º Amarás a Dios sobre todas las cosas',q:['¿Rezo con regularidad o me olvido de Dios durante semanas?','¿He dudado voluntariamente de la fe o la he escondido por vergüenza?','¿He recurrido a horóscopos, tarot, brujería u otras prácticas ocultas?','¿Qué ocupa el primer lugar en mi vida: el dinero, el trabajo, el placer, la imagen?']},
{n:'2.º No tomarás el nombre de Dios en vano',q:['¿He usado el nombre de Dios, de la Virgen o de los santos con ligereza, enojo o burla?','¿He maldecido o blasfemado?','¿He faltado a promesas hechas a Dios?']},
{n:'3.º Santificarás las fiestas',q:['¿He faltado a Misa en domingo o fiesta de guardar sin motivo grave?','¿Llegué tarde o me distraje a propósito?','¿He dedicado el domingo al descanso, a Dios y a la familia?']},
{n:'4.º Honrarás a tu padre y a tu madre',q:['¿He sido respetuoso y agradecido con mis padres y familiares?','¿Cuido de mi familia, especialmente de los mayores o enfermos?','Si soy padre o madre: ¿doy buen ejemplo y educo en la fe?','¿Cumplo mis deberes con las autoridades legítimas y con mi trabajo?']},
{n:'5.º No matarás',q:['¿He dañado a alguien con golpes, insultos o desprecio?','¿Guardo rencor, odio o deseos de venganza?','¿Cuido mi salud, o abuso del alcohol, drogas o la imprudencia al manejar?','¿He participado, aconsejado o apoyado un aborto o la eutanasia?']},
{n:'6.º No cometerás actos impuros',q:['¿He vivido la castidad propia de mi estado de vida (soltero, casado, consagrado)?','¿He consentido actos o relaciones contrarias a la pureza?','¿He sido fiel a mi cónyuge o prometido(a)?']},
{n:'7.º No robarás',q:['¿He tomado algo ajeno, o hecho trampa en el trabajo, los estudios o los negocios?','¿Pago mis deudas y salarios con justicia, o retraso el pago pudiendo hacerlo?','¿Soy generoso con quienes pasan necesidad?','¿Gasto de forma irresponsable lo que otros necesitan de mí?']},
{n:'8.º No darás falso testimonio ni mentirás',q:['¿He mentido, exagerado o engañado?','¿He hablado mal de otros (chismes, calumnias, murmuración)?','¿He juzgado a otros sin conocer la verdad?','¿He revelado secretos que debía guardar?']},
{n:'9.º No consentirás pensamientos ni deseos impuros',q:['¿Cuido lo que miro, leo o veo en redes y pantallas?','¿Consiento pensamientos o fantasías contra la pureza?','¿Evito las ocasiones que me hacen caer?']},
{n:'10.º No codiciarás los bienes ajenos',q:['¿He sentido envidia, celos o ambición desordenada?','¿Soy agradecido por lo que tengo?','¿Vivo apegado a lo material?']}
];
